query:
SELECT p.id, p.clientAccountId, p.clientName, p.clientEmail, p.status, p.currentStage, p.websiteDomain 
FROM projects p 
WHERE p.clientAccountId = 120001 OR p.clientEmail LIKE '%stylist%';

SELECT COUNT(*) as total_projects FROM projects;

